// ── Read helpers for the analysis tools ──────────────────────────────────────
// Result-size caps: tool results are model input (assistant.ts truncates at
// MAX_TOOL_RESULT_CHARS) — cap list payloads and report the omitted count
// instead of letting a fresh 3-month schedule flood the context.
const MAX_GAPS = 60;
const MAX_OPEN_SLOTS = 40;
const MAX_WHO_ROWS = 300;
const MAX_AVAILABILITY_ROWS = 200;

// PostgREST caps un-ranged selects (~1000 rows by default), so ANY multi-row
// read here could silently truncate — understating coverage or conflicts as
// fact. Version-scoped slot reads are NOT exempt: a single version can exceed
// the cap (live repro: 2,201 slot rows across current versions). Every such
// read pages with count:'exact' + .range() until every row has arrived
// (dashboard fetchRollupRows precedent), throwing instead of returning
// partial data. `buildQuery` must return a FRESH filtered builder on each
// call, selecting with { count: 'exact' }; order/range are appended here.
const PAGE_SIZE = 1000;
const MAX_PAGES = 20;
async function pagedSelect<T>(
  label: string,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  buildQuery: () => any,
): Promise<T[]> {
  const rows: T[] = [];
  for (let page = 0; page < MAX_PAGES; page++) {
    const from = page * PAGE_SIZE;
    const { data, error, count } = await buildQuery()
      .order('id', { ascending: true }) // stable order — required for coherent pages
      .range(from, from + PAGE_SIZE - 1);
    if (error) throw new Error(`${label} read failed: ${error.message}`);
    if (count == null) throw new Error(`${label} read failed: row count unavailable (possible truncation)`);
    const batch = (data ?? []) as T[];
    rows.push(...batch);
    if (rows.length >= count) return rows;
    if (batch.length === 0) {
      throw new Error(`${label} read failed: pagination stalled at ${rows.length} of ${count} rows`);
    }
  }
  throw new Error(`${label} read failed: exceeded the ${MAX_PAGES}-page budget (${rows.length} rows)`);
}

interface VersionSlotRow {
  id: string;
  slot_date: string;
  day_type: string;
  code: string;
  category: string;
  requiresPostCallRule: boolean;
  assignedProviderId: string | null;
  // validation_flags stored on a non-assigned (open) row, if any.
  openFlags: unknown[] | null;
}

// Version-scoped slot+assignment load — the same shape get_grid /
// get_schedule_context read, normalized through embedArray so both PostgREST
// embed shapes (one-to-one object vs array) work. Errors THROW: a failed read
// must never surface as zero coverage / zero calls (get_schedule_context's
// hardened pattern). Paged: version-scoped is no exemption from the PostgREST
// row cap.
//
// CROSS-LINK: the filled-predicate here and in get_grid (`provider_id &&
// assignment_status === 'assigned'`) must stay in agreement with the
// dashboard's fills() in src/app/(scheduling)/dashboard/queries.ts (provider_id
// && status ∉ {canceled, declined}). They agree on all data the app writes
// today ('assigned'/'open' only); if pending/external_fill or similar are ever
// written, revisit both together.
async function loadVersionSlotRows(
  sb: SchedulingClient,
  ctx: ScheduleCtx,
  range?: { start: string; end: string },
): Promise<VersionSlotRow[]> {
  const data = await pagedSelect<Record<string, unknown>>('schedule slots', () => {
    let q = sb
      .from('schedule_slots')
      .select('id, slot_date, derived_day_type, shift_types(code, category, requires_post_call_rule), assignments(provider_id, assignment_status, validation_flags)', { count: 'exact' })
      .eq('schedule_version_id', ctx.versionId);
    if (range) q = q.gte('slot_date', range.start).lte('slot_date', range.end);
    return q;
  });

  const rows = (data as Array<Record<string, unknown>>).map(r => {
    const st = embedArray(r.shift_types as never)[0] as
      { code?: string; category?: string; requires_post_call_rule?: boolean } | undefined;
    const assignments = embedArray(r.assignments as never) as Array<{
      provider_id: string | null; assignment_status: string; validation_flags?: unknown;
    }>;
    const assigned = assignments.find(a => a.provider_id && a.assignment_status === 'assigned');
    const flagsRow = assigned ? null : assignments.find(a => Array.isArray(a.validation_flags));
    return {
      id: r.id as string,
      slot_date: r.slot_date as string,
      day_type: (r.derived_day_type as string | null) ?? 'weekday',
      code: st?.code ?? '?',
      // A missing shift_types embed must NOT fabricate call-ness — fall back
      // to a non-call sentinel so fairness math never counts a mystery slot.
      category: st?.category ?? 'unknown',
      requiresPostCallRule: st?.requires_post_call_rule === true,
      assignedProviderId: assigned?.provider_id ?? null,
      openFlags: flagsRow ? (flagsRow.validation_flags as unknown[]) : null,
    };
  });
  // pagedSelect orders by id (paging coherence); consumers want date order.
  rows.sort((a, b) => a.slot_date.localeCompare(b.slot_date) || a.code.localeCompare(b.code));
  return rows;
}

interface CallPoolProvider {
  id: string;
  name: string;
  fte: number | null; // null = no employment profile row
  inPool: boolean;
}

// Call-pool membership for read-only reports. KEEP IN SYNC with
// loadGenerationContext §3 (genContext.ts): default pool = ACTIVE home-site
// providers flagged call_taker or partial_call_taker; a schedule override pool
// is exactly those UUIDs (that have an employment profile and are active —
// genContext gates the providers query on status='active'). The status gate
// runs in JS rather than the query so INACTIVE rows are still returned: a
// departed provider holding historical assignments must be nameable in
// reports, but must never enter the pool (their FTE would deflate everyone's
// expected share and the prompt's "propose named fixes" flow could recommend
// assigning someone who left).
async function loadCallPool(
  sb: SchedulingClient,
  ctx: ScheduleCtx,
): Promise<{ providers: CallPoolProvider[]; poolIds: Set<string>; poolFte: number }> {
  const override = ctx.overrideProviderIds && ctx.overrideProviderIds.length > 0
    ? ctx.overrideProviderIds
    : null;
  const data = await pagedSelect<Record<string, unknown>>('providers', () => {
    let q = sb
      .from('providers')
      .select('id, last_name, short_display_name, provider_type, status, provider_employment_profiles(fte_value, home_site_id, call_taker, partial_call_taker)', { count: 'exact' });
    if (override) q = q.in('id', override);
    return q;
  });

  const providers: CallPoolProvider[] = [];
  const poolIds = new Set<string>();
  let poolFte = 0;
  for (const row of data) {
    const profile = embedArray(row.provider_employment_profiles as never)[0] as
      { home_site_id?: string; call_taker?: boolean; partial_call_taker?: boolean } | undefined;
    // fte defaults to 1 for profiled providers (genContext parity: `|| 1`).
    const fte = profile ? (parseEmbeddedFte(row.provider_employment_profiles) || 1) : null;
    const inPool = row.status === 'active' && !!profile && (override
      ? true
      : profile.home_site_id === ctx.siteId && (profile.call_taker === true || profile.partial_call_taker === true));
    const p: CallPoolProvider = {
      id: row.id as string,
      name: (row.short_display_name as string) || (row.last_name as string) || (row.id as string),
      fte,
      inPool,
    };
    providers.push(p);
    if (inPool) { poolIds.add(p.id); poolFte += fte ?? 1; }
  }
  return { providers, poolIds, poolFte };
}

// Population stdev — sync copy of populationStdev in metrics.ts (not
// exported there; scoreSolution needs a full SolutionPlan+GenerationContext,
// which a read tool must not fabricate). Keep the math identical.
function populationStdev(values: number[]): number {
  if (values.length === 0) return 0;
  const mean = values.reduce((s, v) => s + v, 0) / values.length;
  const variance = values.reduce((s, v) => s + (v - mean) * (v - mean), 0) / values.length;
  return Math.sqrt(variance);
}

function nameList(ids: Iterable<string>, nameByPid: Map<string, string>, max = 5): string {
  const names = [...ids].map(id => nameByPid.get(id) ?? id);
  const shown = names.slice(0, max).join(', ');
  return names.length > max ? `${shown}, …` : shown;
}
