// The undo window: the availability span the snapshot captures and the revert
// delete-new pass re-reads (snapshot.ts readOrgAvailabilityWindow). Any
// availability WRITE must overlap it — a row entirely outside would escape the
// snapshot baseline AND the delete-new pass, leaving an un-undoable approved
// blocking row (invariant-2 data).
function assertOverlapsUndoWindow(
  ctx: ScheduleCtx,
  startDate: string,
  endDate: string,
  what: string,
): void {
  const winStart = addDays(ctx.dateStart, -AVAIL_WINDOW_DAYS);
  const winEnd = addDays(ctx.dateEnd, AVAIL_WINDOW_DAYS);
  if (startDate > winEnd || endDate < winStart) {
    throw new ToolInputError(
      `${what} (${startDate} → ${endDate}) is entirely outside this schedule's undo window (${winStart} → ${winEnd}), so the change could not be undone from here. Tell the scheduler to open the schedule covering those dates and record it there.`,
    );
  }
}

// Org guard shared by the intake writers (mirrors POST /availability's check):
// the provider must exist and belong to this site's organization.
async function assertProviderInSiteOrg(
  sb: SchedulingClient,
  siteId: string,
  providerId: string,
): Promise<void> {
  const [provRes, siteRes] = await Promise.all([
    sb.from('providers').select('organization_id').eq('id', providerId).maybeSingle(),
    sb.from('sites').select('organization_id').eq('id', siteId).maybeSingle(),
  ]);
  if (provRes.error) throw new Error(`provider org lookup failed: ${provRes.error.message}`);
  if (siteRes.error) throw new Error(`site org lookup failed: ${siteRes.error.message}`);
  if (!provRes.data) {
    throw new ToolInputError(
      `provider ${providerId} not found — resolve the provider via get_schedule_context`,
    );
  }
  const provOrg = (provRes.data as { organization_id?: string }).organization_id;
  const siteOrg = (siteRes.data as { organization_id?: string } | null)?.organization_id;
  if (!siteOrg || provOrg !== siteOrg) {
    throw new ToolInputError(
      `provider ${providerId} does not belong to this site's organization — you can only write for this site's providers`,
    );
  }
}

// Availability is a PROVIDER-level fact (every engine reads it by provider_id,
// never by site_id — genContext/dayShiftAutoGen/batchValidate), so we scope
// list_availability + the org check to the site's ORGANIZATION rather than a
// single site. Returns the org's provider ids and a display-name map.
async function loadOrgProviders(
  sb: SchedulingClient,
  siteId: string,
): Promise<{ ids: string[]; nameByPid: Map<string, string> }> {
  const { data: site, error: siteErr } = await sb
    .from('sites').select('organization_id').eq('id', siteId).maybeSingle();
  if (siteErr) throw new Error(`site org lookup failed: ${siteErr.message}`);
  const orgId = (site as { organization_id?: string } | null)?.organization_id;
  const nameByPid = new Map<string, string>();
  if (!orgId) return { ids: [], nameByPid };
  const rows = await pagedSelect<Record<string, unknown>>('providers', () =>
    sb.from('providers')
      .select('id, last_name, short_display_name', { count: 'exact' })
      .eq('organization_id', orgId));
  const ids: string[] = [];
  for (const r of rows) {
    const id = r.id as string;
    ids.push(id);
    nameByPid.set(id, (r.short_display_name as string) || (r.last_name as string) || id);
  }
  return { ids, nameByPid };
}

export function createToolExecutors(deps?: Partial<ToolEngineDeps>): Record<string, ToolExecutor> {
  const engine: ToolEngineDeps = {
    autoGenerate: deps?.autoGenerate ?? realAutoGenerate,
    autoGenerateDayShifts: deps?.autoGenerateDayShifts ?? realAutoGenerateDayShifts,
  };

  return {
    async get_schedule_context(sb, ctx) {
      // The slot-id read is paged (a version can exceed PostgREST's row cap —
      // see pagedSelect); it throws directly, rejecting the Promise.all, which
      // is the same honest-failure outcome as the collective readErr check.
      const [siteRes, shiftTypesRes, patternRes, ruleSetsRes, providersRes, slotIdRows] = await Promise.all([
        sb.from('sites').select('id, name, short_name').eq('id', ctx.siteId).maybeSingle(),
        sb.from('shift_types')
          .select('id, code, name, category, call_rank, relief_rank, is_overlay, generation_engine, requires_post_call_rule, start_time, end_time')
          .eq('site_id', ctx.siteId),
        sb.from('call_patterns')
          .select('id, name, source, definition, updated_at')
          .eq('site_id', ctx.siteId)
          .eq('status', 'active')
          .maybeSingle(),
        sb.from('rule_sets').select('id, name, status').eq('site_id', ctx.siteId).eq('status', 'active'),
        sb.from('providers').select('id, last_name, short_display_name, provider_type'),
        pagedSelect<{ id: string }>('schedule slots', () =>
          sb.from('schedule_slots').select('id', { count: 'exact' }).eq('schedule_version_id', ctx.versionId)),
      ]);

      // A failed read must surface as a tool error — presenting zeros/empties
      // as fact would have the model reason from fake-clean state.
      const readErr = [siteRes, shiftTypesRes, patternRes, ruleSetsRes, providersRes]
        .map(r => (r as { error?: { message: string } | null }).error?.message)
        .find(Boolean);
      if (readErr) throw new Error(`schedule context read failed: ${readErr}`);

      const ruleSetIds = ((ruleSetsRes.data ?? []) as Array<{ id: string }>).map(r => r.id);
      let rules: unknown[] = [];
      if (ruleSetIds.length > 0) {
        const { data, error } = await sb
          .from('rule_definitions')
          .select('id, rule_set_id, rule_name, rule_category, hard_constraint, is_active, explanation_text')
          .in('rule_set_id', ruleSetIds);
        if (error) throw new Error(`rule_definitions read failed: ${error.message}`);
        rules = data ?? [];
      }

      const slotIds = slotIdRows.map(s => s.id);
      let assignedCount = 0;
      for (const ids of chunk(slotIds, READ_CHUNK)) {
        const { data, error } = await sb
          .from('assignments')
          .select('id, assignment_status')
          .in('schedule_slot_id', ids)
          .eq('assignment_status', 'assigned');
        if (error) throw new Error(`assignments count read failed: ${error.message}`);
        assignedCount += (data ?? []).length;
      }

      const shiftTypes = (shiftTypesRes.data ?? []) as Array<{ code: string }>;
      const pattern = patternRes.data as { definition?: unknown } | null;
      const warnings = pattern?.definition
        ? patternWarnings(
            pattern.definition as Parameters<typeof patternWarnings>[0],
            new Set(shiftTypes.map(s => s.code)),
          )
        : ['No active call pattern for this site — generation falls back to the classic default.'];

      return {
        summary: 'Read schedule context',
        result: {
          schedule: {
            id: ctx.scheduleId, name: ctx.scheduleName,
            date_start: ctx.dateStart, date_end: ctx.dateEnd,
            version_id: ctx.versionId,
            override_pool_size: ctx.overrideProviderIds?.length ?? null,
          },
          site: siteRes.data ?? { id: ctx.siteId },
          shift_types: shiftTypesRes.data ?? [],
          active_call_pattern: patternRes.data ?? null,
          rule_sets: ruleSetsRes.data ?? [],
          rules,
          providers: providersRes.data ?? [],
          metrics: { total_slots: slotIds.length, assigned: assignedCount },
          warnings,
        },
      };
    },

    async get_grid(sb, ctx) {
      type GridAssignment = {
        provider_id: string | null; assignment_status: string;
        providers: { last_name?: string; short_display_name?: string } | null;
      };
      type GridRow = {
        id: string; slot_date: string; derived_day_type: string | null;
        shift_types: { code?: string } | null;
        // UNIQUE(schedule_slot_id) → PostgREST returns this embed as a single
        // OBJECT (or null) against the live DB; dev fakes return arrays.
        assignments?: GridAssignment | GridAssignment[] | null;
      };
      // Paged: a version can exceed PostgREST's row cap (see pagedSelect) —
      // a silently capped grid would render missing slots as nonexistent.
      const rows = await pagedSelect<GridRow>('grid', () => sb
        .from('schedule_slots')
        .select('id, slot_date, slot_index, derived_day_type, shift_types(code), assignments(provider_id, assignment_status, providers(last_name, short_display_name))', { count: 'exact' })
        .eq('schedule_version_id', ctx.versionId));
      // pagedSelect orders by id (paging coherence); the grid reads by date.
      rows.sort((a, b) => a.slot_date.localeCompare(b.slot_date));
      const lines = rows.map(r => {
        const code = r.shift_types?.code ?? '?';
        const a = embedArray(r.assignments)[0];
        const who = a && a.provider_id && a.assignment_status === 'assigned'
          ? (a.providers?.short_display_name || a.providers?.last_name || a.provider_id)
          : 'OPEN';
        return `${r.slot_date} ${r.derived_day_type ?? ''} ${code} slot=${r.id} → ${who}`;
      });
      return {
        summary: 'Read grid',
        result: { slots: rows.length, grid: lines.join('\n') },
      };
    },

    // ── Read/analysis tools (ui-v1 Task 8) — all READ-ONLY, none mutating ────

    async get_coverage_summary(sb, ctx, input) {
      const parsed = parseWith(CoverageInputSchema, input);
      const start = parsed.date_start ?? ctx.dateStart;
      const end = parsed.date_end ?? ctx.dateEnd;
      if (start > end) {
        throw new ToolInputError(`date_start (${start}) must be on or before date_end (${end})`);
      }
      const rows = await loadVersionSlotRows(sb, ctx, { start, end });

      let filled = 0;
      const byCode: Record<string, { filled: number; open: number }> = {};
      const gaps: Array<{ slot_id: string; date: string; day_type: string; code: string }> = [];
      for (const r of rows) {
        const agg = (byCode[r.code] ??= { filled: 0, open: 0 });
        if (r.assignedProviderId) {
          agg.filled++;
          filled++;
        } else {
          agg.open++;
          gaps.push({ slot_id: r.id, date: r.slot_date, day_type: r.day_type, code: r.code });
        }
      }
      const open = rows.length - filled;
      return {
        summary: `Coverage ${start} → ${end}: ${filled}/${rows.length} filled, ${open} open`,
        result: {
          date_start: start,
          date_end: end,
          total_slots: rows.length,
          filled,
          open,
          by_code: byCode,
          gaps: gaps.slice(0, MAX_GAPS),
          omitted_gaps: Math.max(0, gaps.length - MAX_GAPS),
        },
      };
    },

    async get_fairness_report(sb, ctx) {
      const pool = await loadCallPool(sb, ctx);
      const rows = await loadVersionSlotRows(sb, ctx);

      // Call-ness is the shift type's CATEGORY, never a code literal
      // (metrics.ts convention — custom call codes count exactly like C1).
      const callsByPid = new Map<string, { total: number; byBucket: Record<string, number> }>();
      let totalCalls = 0;
      for (const r of rows) {
        if (!r.assignedProviderId || r.category !== 'call') continue;
        totalCalls++;
        const entry = callsByPid.get(r.assignedProviderId) ?? { total: 0, byBucket: {} };
        entry.total++;
        const bucket = dayTypeBucket(r.day_type);
        entry.byBucket[bucket] = (entry.byBucket[bucket] ?? 0) + 1;
        callsByPid.set(r.assignedProviderId, entry);
      }

      const byId = new Map(pool.providers.map(p => [p.id, p]));
      // Report = pool members + anyone holding a call in this version.
      const reportIds = new Set<string>([
        ...pool.poolIds,
        ...callsByPid.keys(),
      ]);
      const providers = [...reportIds].map(id => {
        const p = byId.get(id);
        const calls = callsByPid.get(id);
        const inPool = pool.poolIds.has(id);
        const fte = p?.fte ?? null;
        // Expected = FTE-proportional share of THIS version's call assignments.
        // Mirrors the base-share term of computeBucketTargets (genContext.ts)
        // normalized over pool FTE so expectations sum to the assigned total;
        // par-level scaling + historical deficit carry-forward are generate-time
        // machinery and deliberately absent from this read-only report.
        const expected = inPool && pool.poolFte > 0 ? (totalCalls * (fte ?? 1)) / pool.poolFte : null;
        return {
          provider_id: id,
          name: p?.name ?? id,
          fte,
          in_pool: inPool,
          calls_total: calls?.total ?? 0,
          calls_by_bucket: calls?.byBucket ?? {},
          expected,
          delta: expected === null ? null : (calls?.total ?? 0) - expected,
        };
      }).sort((a, b) =>
        Number(b.in_pool) - Number(a.in_pool) || (b.delta ?? 0) - (a.delta ?? 0) || a.name.localeCompare(b.name));

      // Fairness stdev over pool calls-per-FTE ratios — same ratio + stdev
      // semantics as scoreSolution in metrics.ts (block scope; historical
      // counts are the engine's concern, not this report's).
      const ratios = pool.providers
        .filter(p => p.inPool)
        .map(p => (callsByPid.get(p.id)?.total ?? 0) / Math.max(p.fte ?? 1, 0.01));
      const stdev = populationStdev(ratios);

      const notes: string[] = [];
      if (pool.poolIds.size === 0) {
        notes.push('No call-pool providers found (home-site call-takers or schedule override) — expected/delta unavailable.');
      }
      const outOfPool = providers.filter(p => !p.in_pool);
      if (outOfPool.length > 0) {
        notes.push(`${outOfPool.length} provider(s) hold call assignments but are outside the call pool.`);
      }
      return {
        summary: `Fairness: ${totalCalls} call assignment(s) across ${pool.poolIds.size} pool provider(s), stdev/FTE ${stdev.toFixed(2)}`,
        result: {
          total_call_assignments: totalCalls,
          pool_size: pool.poolIds.size,
          pool_fte: pool.poolFte,
          stdev_calls_per_fte: stdev,
          providers,
          notes,
        },
      };
    },

    async find_unfilled(sb, ctx) {
      const rows = await loadVersionSlotRows(sb, ctx);
      const pool = await loadCallPool(sb, ctx);
      const nameByPid = new Map(pool.providers.map(p => [p.id, p.name]));
      const openSlots = rows.filter(r => !r.assignedProviderId);

      // Same-date context from the already-loaded version rows.
      const assignedByDate = new Map<string, Set<string>>();
      const postCallSourceByDate = new Map<string, Set<string>>();
      for (const r of rows) {
        if (!r.assignedProviderId) continue;
        let sameDay = assignedByDate.get(r.slot_date);
        if (!sameDay) { sameDay = new Set(); assignedByDate.set(r.slot_date, sameDay); }
        sameDay.add(r.assignedProviderId);
        if (r.requiresPostCallRule) {
          let pc = postCallSourceByDate.get(r.slot_date);
          if (!pc) { pc = new Set(); postCallSourceByDate.set(r.slot_date, pc); }
          pc.add(r.assignedProviderId);
        }
      }

      // Blocking availability over the open dates (pool-scoped when a pool
      // exists). PENDING blocks — clinical invariant 2. Per-date decisions go
      // through the single-homed isDateBlocked (shared.ts), so live
      // pto_sellback rows override blocking coverage on their dates — a
      // sold-back provider must not be hinted as blocked (they are working).
      // Rows kept whole (sell-back rows included) so the helper can decide.
      const blockingByPid = new Map<string, Array<{
        availability_type: string; start_date: string; end_date: string; approval_status: string;
      }>>();
      if (openSlots.length > 0) {
        const openDates = openSlots.map(s => s.slot_date).sort();
        // Not version-scoped → paged (a truncated read would undercount
        // blocked providers and make an open slot look easier than it is).
        const data = await pagedSelect<{
          provider_id: string; availability_type: string;
          start_date: string; end_date: string; approval_status: string;
        }>('availability', () => {
          let q = sb
            .from('provider_availability')
            .select('id, provider_id, availability_type, start_date, end_date, approval_status', { count: 'exact' })
            .lte('start_date', openDates[openDates.length - 1])
            .gte('end_date', openDates[0]);
          if (pool.poolIds.size > 0) q = q.in('provider_id', [...pool.poolIds]);
          return q;
        });
        for (const a of data) {
          if (!isBlockingAvailability(a) && !isActiveSellback(a)) continue;
          const list = blockingByPid.get(a.provider_id) ?? [];
          list.push({
            availability_type: a.availability_type, start_date: a.start_date,
            end_date: a.end_date, approval_status: a.approval_status,
          });
          blockingByPid.set(a.provider_id, list);
        }
      }

      // Hints are cheap DERIVED CONTEXT, emitted only when the underlying count
      // is non-zero — never fabricated. Full per-candidate blocker analysis
      // needs eligibility over a GenerationContext (generate-time machinery);
      // trimUnfilled applies only to real candidate arrays, which a read tool
      // doesn't have — we reuse only its cap so hint volume matches the
      // engine's rejection-trimming convention.
      const slots = openSlots.map(s => {
        const hints: string[] = [];
        const blocked = new Set<string>();
        for (const [pid, rows] of blockingByPid) {
          // RAW ranges as before (this hint never bookended).
          if (isDateBlocked(rows, s.slot_date)) blocked.add(pid);
        }
        if (blocked.size > 0) {
          // With no pool the "N of P pool providers" framing is nonsense
          // ("3 of 0") — fall back to a plain provider count.
          const scope = pool.poolIds.size > 0
            ? `${blocked.size} of ${pool.poolIds.size} pool providers`
            : `${blocked.size} provider(s)`;
          hints.push(`${scope} blocked by PTO/unavailability on this date (${nameList(blocked, nameByPid)})`);
        }
        const sameDay = assignedByDate.get(s.slot_date) ?? new Set<string>();
        if (sameDay.size > 0) {
          hints.push(`${sameDay.size} provider(s) already assigned on this date in this schedule (${nameList(sameDay, nameByPid)})`);
        }
        const prevDate = addDays(s.slot_date, -1);
        const postCall = postCallSourceByDate.get(prevDate) ?? new Set<string>();
        if (postCall.size > 0) {
          hints.push(`${postCall.size} provider(s) post-call from a 24h call on ${prevDate} (${nameList(postCall, nameByPid)})`);
        }
        if (s.openFlags && s.openFlags.length > 0) {
          hints.push(`${s.openFlags.length} stored validation flag(s) on the open slot row`);
        }
        return {
          slot_id: s.id,
          date: s.slot_date,
          day_type: s.day_type,
          code: s.code,
          hints: hints.slice(0, MAX_CANDIDATE_REASONS),
        };
      });

      return {
        summary: `${openSlots.length} unfilled slot(s)`,
        result: {
          open_count: openSlots.length,
          pool_size: pool.poolIds.size,
          slots: slots.slice(0, MAX_OPEN_SLOTS),
          omitted_slots: Math.max(0, slots.length - MAX_OPEN_SLOTS),
          hint_note: 'Hints are schedule-derived context, not a per-candidate eligibility analysis; engine-verified candidate rejections appear only in generation results (when the scheduler asks for generation to be re-run).',
        },
      };
    },

    async who_is_on(sb, ctx, input) {
      const parsed = parseWith(WhoIsOnInputSchema, input);
      if (!parsed.provider_id && !parsed.date) {
        throw new ToolInputError('Provide at least one of provider_id or date.');
      }
      const w = parsed.window_days ?? 0;
      const range = parsed.date
        ? { start: addDays(parsed.date, -w), end: addDays(parsed.date, w) }
        : { start: ctx.dateStart, end: ctx.dateEnd };

      interface WhoRow {
        date: string; day_type: string; code: string; site: string;
        provider_id: string; provider: string;
        schedule_version_id: string; in_current_version: boolean;
      }
      type SlotEmbed = {
        id?: string; slot_date?: string; site_id?: string; derived_day_type?: string | null;
        schedule_version_id?: string;
        shift_types?: { code?: string } | Array<{ code?: string }> | null;
        sites?: { name?: string; short_name?: string } | Array<{ name?: string; short_name?: string }> | null;
      };
      type ProviderEmbed = { last_name?: string; short_display_name?: string };
      const mapRow = (providerId: string, prov: ProviderEmbed | undefined, slot: SlotEmbed): WhoRow => ({
        date: slot.slot_date ?? '?',
        day_type: (slot.derived_day_type as string | null) ?? 'weekday',
        code: (embedArray(slot.shift_types)[0] as { code?: string } | undefined)?.code ?? '?',
        site: (() => {
          const site = embedArray(slot.sites)[0] as { name?: string; short_name?: string } | undefined;
          return site?.short_name || site?.name || slot.site_id || '?';
        })(),
        provider_id: providerId,
        provider: prov?.short_display_name || prov?.last_name || providerId,
        schedule_version_id: slot.schedule_version_id ?? '?',
        in_current_version: slot.schedule_version_id === ctx.versionId,
      });

      const out: WhoRow[] = [];
      if (parsed.provider_id) {
        // Provider mode: committed scope (draft isolation, invariant 3) —
        // PUBLISHED versions at any site PLUS this schedule's current version.
        // An unpublished draft of another schedule is not a real booking and
        // must not read as one. PostgREST cannot OR across the embedded
        // version_status filter (committedAssignments' documented two-query
        // strategy), so run one paged leg per scope and dedupe by assignment id
        // (a published current-version row satisfies both). Still paged:
        // cross-site published history is NOT version-scoped.
        const providerQuery = () => sb
          .from('assignments')
          .select('id, provider_id, assignment_status, providers(last_name, short_display_name), schedule_slots!inner(id, slot_date, site_id, derived_day_type, schedule_version_id, schedule_versions!inner(version_status), shift_types(code), sites(name, short_name))', { count: 'exact' })
          .eq('provider_id', parsed.provider_id)
          .eq('assignment_status', 'assigned')
          .gte('schedule_slots.slot_date', range.start)
          .lte('schedule_slots.slot_date', range.end);
        const published = await pagedSelect<Record<string, unknown>>('assignments', () =>
          filterPublishedVersions(providerQuery()));
        const current = await pagedSelect<Record<string, unknown>>('assignments', () =>
          providerQuery().eq('schedule_slots.schedule_version_id', ctx.versionId));
        const seen = new Set<unknown>();
        for (const a of [...published, ...current]) {
          if (a.id != null) {
            if (seen.has(a.id)) continue;
            seen.add(a.id);
          }
          const slot = embedArray(a.schedule_slots as never)[0] as SlotEmbed | undefined;
          if (!slot) continue;
          const prov = embedArray(a.providers as never)[0] as ProviderEmbed | undefined;
          out.push(mapRow(a.provider_id as string, prov, slot));
        }
      } else {
        // Date mode: same committed scope — slots in PUBLISHED versions (any
        // site) plus this schedule's current version; other drafts invisible.
        // Two paged legs merged by slot id (the Map dedupes a published
        // current-version slot), then assignments chunked at READ_CHUNK.
        const slotQuery = () => sb
          .from('schedule_slots')
          .select('id, slot_date, site_id, derived_day_type, schedule_version_id, schedule_versions!inner(version_status), shift_types(code), sites(name, short_name)', { count: 'exact' })
          .gte('slot_date', range.start)
          .lte('slot_date', range.end);
        const publishedSlots = await pagedSelect<SlotEmbed & { id: string }>('schedule slots', () =>
          filterPublishedVersions(slotQuery(), 'schedule_versions'));
        const currentSlots = await pagedSelect<SlotEmbed & { id: string }>('schedule slots', () =>
          slotQuery().eq('schedule_version_id', ctx.versionId));
        const slotById = new Map([...publishedSlots, ...currentSlots].map(s => [s.id, s]));
        // The per-chunk assignment reads need no paging: UNIQUE(schedule_slot_id)
        // bounds each chunk at READ_CHUNK rows, well under the PostgREST cap.
        for (const ids of chunk([...slotById.keys()], READ_CHUNK)) {
          const { data, error: aErr } = await sb
            .from('assignments')
            .select('id, schedule_slot_id, provider_id, assignment_status, providers(last_name, short_display_name)')
            .in('schedule_slot_id', ids)
            .eq('assignment_status', 'assigned');
          if (aErr) throw new Error(`assignments read failed: ${aErr.message}`);
          for (const a of (data ?? []) as Array<Record<string, unknown>>) {
            const slot = slotById.get(a.schedule_slot_id as string);
            if (!slot || !a.provider_id) continue;
            const prov = embedArray(a.providers as never)[0] as ProviderEmbed | undefined;
            out.push(mapRow(a.provider_id as string, prov, slot));
          }
        }
      }

      out.sort((a, b) => a.date.localeCompare(b.date) || a.site.localeCompare(b.site) || a.code.localeCompare(b.code));
      return {
        summary: `${out.length} assignment(s) ${range.start} → ${range.end}`,
        result: {
          date_start: range.start,
          date_end: range.end,
          total: out.length,
          rows: out.slice(0, MAX_WHO_ROWS),
          omitted: Math.max(0, out.length - MAX_WHO_ROWS),
        },
      };
    },

    async update_call_pattern(sb, ctx, input) {
      const parsed = parseWith(UpdatePatternInputSchema, input);
      const name = parsed.name ?? 'Assistant pattern';
      const { data, error } = await replaceActivePattern(sb, ctx.siteId, parsed.definition, {
        name, source: 'assistant',
      });
      if (error) throw new Error(`call pattern replace failed: ${error.message}`);
      return {
        summary: `Call pattern replaced: "${name}"`,
        result: { ok: true, pattern_id: (data as { id?: string } | null)?.id ?? null, name },
      };
    },

    async upsert_shift_type(sb, ctx, input) {
      const parsed = parseWith(AssistantShiftTypeInput, input);
      const { data: existing, error: selErr } = await sb
        .from('shift_types')
        .select('id')
        .eq('site_id', ctx.siteId)
        .eq('code', parsed.code)
        .maybeSingle();
      if (selErr) throw new Error(`shift_type lookup failed: ${selErr.message}`);

      if (existing) {
        const patch = parseWith(ShiftTypePatchSchema, { ...parsed, site_id: ctx.siteId });
        const { data, error } = await sb
          .from('shift_types').update(patch).eq('id', existing.id).select().single();
        if (error) throw new Error(`shift_type update failed: ${error.message}`);
        return {
          summary: `Shift type updated: ${parsed.code}`,
          result: { ok: true, action: 'updated', shift_type: data },
        };
      }
      const insert = parseWith(ShiftTypeUpsertSchema, {
        name: parsed.code, // default when the model omits a display name
        ...parsed,
        site_id: ctx.siteId,
      });
      const { data, error } = await sb.from('shift_types').insert(insert).select().single();
      if (error) throw new Error(`shift_type insert failed: ${error.message}`);
      return {
        summary: `Shift type created: ${parsed.code}`,
        result: { ok: true, action: 'created', shift_type: data },
      };
    },

    async upsert_rule_definition(sb, ctx, input) {
      // condition/action arrive as JSON strings (strict-schema constraint) —
      // decode before zod validation.
      const normalized = decodeJsonStringFields(input, ['condition', 'action']);
      const parsed = parseWith(AssistantRuleInput, normalized);
      const { data: ruleSets, error: rsErr } = await sb
        .from('rule_sets').select('id').eq('site_id', ctx.siteId).eq('status', 'active');
      if (rsErr) throw new Error(`rule_sets load failed: ${rsErr.message}`);
      const ruleSetId = ((ruleSets ?? []) as Array<{ id: string }>)[0]?.id;
      if (!ruleSetId) {
        throw new ToolInputError('This site has no active rule set — create one in the Rules UI before writing rule definitions.');
      }

      const { data: existing, error: selErr } = await sb
        .from('rule_definitions')
        .select('id')
        .eq('rule_set_id', ruleSetId)
        .eq('rule_name', parsed.rule_name)
        .maybeSingle();
      if (selErr) throw new Error(`rule_definition lookup failed: ${selErr.message}`);

      const payload = parseWith(RuleDefinitionUpsertSchema, { ...parsed, rule_set_id: ruleSetId });
      if (existing) {
        const { data, error } = await sb
          .from('rule_definitions').update(payload).eq('id', existing.id).select().single();
        if (error) throw new Error(`rule_definition update failed: ${error.message}`);
        return {
          summary: `Rule updated: ${parsed.rule_name}`,
          result: { ok: true, action: 'updated', rule: data },
        };
      }
      const { data, error } = await sb
        .from('rule_definitions').insert(payload).select().single();
      if (error) throw new Error(`rule_definition insert failed: ${error.message}`);
      return {
        summary: `Rule created: ${parsed.rule_name}`,
        result: { ok: true, action: 'created', rule: data },
      };
    },

    async assign_provider(sb, ctx, input) {
      const parsed = parseWith(AssignInputSchema, input);
      const outcome = await assignProviderToSlot(sb, parsed.slot_id, parsed.provider_id, ctx.versionId);
      const v = outcome.validation;
      return {
        summary: `Assigned provider to slot (${v.hardCount} hard / ${v.softCount} soft violations)`,
        result: outcome,
      };
    },

    async clear_assignment(sb, ctx, input) {
      const parsed = parseWith(ClearInputSchema, input);
      const outcome = await clearSlotAssignment(sb, parsed.slot_id, ctx.versionId);
      return {
        summary: outcome.cleared
          ? `Cleared assignment (+${outcome.clearedSlotIds.length} linked auto-fills)`
          : 'Slot was already open',
        result: outcome,
      };
    },

    // ── Intake executors (assistant-intake) ─────────────────────────────────

    async list_availability(sb, ctx, input) {
      const parsed = parseWith(ListAvailabilityInputSchema, input);
      const start = parsed.date_start ?? addDays(ctx.dateStart, -AVAIL_WINDOW_DAYS);
      const end = parsed.date_end ?? addDays(ctx.dateEnd, AVAIL_WINDOW_DAYS);
      if (start > end) {
        throw new ToolInputError(`date_start (${start}) must be on or before date_end (${end})`);
      }
      const org = await loadOrgProviders(sb, ctx.siteId);
      let providerIds = org.ids;
      if (parsed.provider_id) {
        if (!org.nameByPid.has(parsed.provider_id)) {
          throw new ToolInputError(
            `provider ${parsed.provider_id} is not in this site's organization — resolve the provider via get_schedule_context`,
          );
        }
        providerIds = [parsed.provider_id];
      }
      if (providerIds.length === 0) {
        return {
          summary: 'No providers in this site’s organization',
          result: { date_start: start, date_end: end, total: 0, rows: [], omitted: 0 },
        };
      }
      // Overlap [start, end]: start_date ≤ end AND end_date ≥ start (mirrors the
      // GET /availability + engine reads). Chunked .in at READ_CHUNK (id lists
      // ride the query string — snapshot.ts convention) and paged within each
      // chunk — not version-scoped, so no exemption from PostgREST's row cap.
      interface AvailRow {
        id: string; provider_id: string; availability_type: string;
        start_date: string; end_date: string; approval_status: string; source: string | null;
      }
      const rows: AvailRow[] = [];
      for (const ids of chunk(providerIds, READ_CHUNK)) {
        rows.push(...await pagedSelect<AvailRow>('availability', () =>
          sb.from('provider_availability')
            .select('id, provider_id, availability_type, start_date, end_date, approval_status, source', { count: 'exact' })
            .in('provider_id', ids)
            .lte('start_date', end)
            .gte('end_date', start)));
      }
      const out = rows.map(r => ({
        id: r.id,
        provider_id: r.provider_id,
        provider: org.nameByPid.get(r.provider_id) ?? r.provider_id,
        availability_type: r.availability_type,
        start_date: r.start_date,
        end_date: r.end_date,
        approval_status: r.approval_status,
        source: r.source ?? null,
      })).sort((a, b) =>
        a.start_date.localeCompare(b.start_date) || a.provider.localeCompare(b.provider));
      return {
        summary: `${out.length} availability entr${out.length === 1 ? 'y' : 'ies'} ${start} → ${end}`,
        result: {
          date_start: start,
          date_end: end,
          total: out.length,
          rows: out.slice(0, MAX_AVAILABILITY_ROWS),
          omitted: Math.max(0, out.length - MAX_AVAILABILITY_ROWS),
        },
      };
    },

    async record_availability(sb, ctx, input) {
      const parsed = parseWith(RecordAvailabilityInputSchema, input);
      if (parsed.end_date < parsed.start_date) {
        throw new ToolInputError(
          `end_date (${parsed.end_date}) must be on or after start_date (${parsed.start_date})`,
        );
      }
      // Undo-window guard: a row entirely outside the snapshot's availability
      // window would escape both the baseline and the revert delete-new pass —
      // an un-undoable approved blocking row. Overlap is sufficient: the
      // snapshot/delete reads use the same overlap semantics, so a partially
      // overlapping row IS captured and IS seen by the delete pass.
      assertOverlapsUndoWindow(ctx, parsed.start_date, parsed.end_date, 'The availability entry');
      await assertProviderInSiteOrg(sb, ctx.siteId, parsed.provider_id);
      // Mirrors POST /availability: all_day, approved (grid virtual rows render
      // approved entries only — pending would steer generation invisibly).
      // source 'assistant' is provenance (the column is free text, default
      // 'manual'). site_id is provenance only — the engines never scope
      // availability by it, so cross-site blocking still holds.
      const row = {
        provider_id: parsed.provider_id,
        site_id: ctx.siteId,
        availability_type: parsed.availability_type,
        start_date: parsed.start_date,
        end_date: parsed.end_date,
        all_day: true,
        notes: parsed.notes ?? null,
        source: 'assistant',
        approval_status: 'approved',
      };
      const { data, error } = await sb
        .from('provider_availability').insert(row).select().single();
      if (error) throw new Error(`availability insert failed: ${error.message}`);
      const range = parsed.end_date !== parsed.start_date
        ? `${parsed.start_date} → ${parsed.end_date}` : parsed.start_date;
      return {
        summary: `Recorded ${parsed.availability_type} for provider ${parsed.provider_id} (${range})`,
        result: { ok: true, availability: data },
      };
    },

    async cancel_availability(sb, ctx, input) {
      const parsed = parseWith(CancelAvailabilityInputSchema, input);
      const { data: existing, error: selErr } = await sb
        .from('provider_availability')
        .select('id, approval_status, provider_id, start_date, end_date')
        .eq('id', parsed.id)
        .maybeSingle();
      if (selErr) throw new Error(`availability lookup failed: ${selErr.message}`);
      if (!existing) {
        throw new ToolInputError(
          `availability entry ${parsed.id} not found — call list_availability for current ids`,
        );
      }
      // Same guards as record_availability: a status flip on a row outside the
      // undo window (or another org) would escape the snapshot baseline and
      // could not be restored on revert.
      assertOverlapsUndoWindow(
        ctx, existing.start_date as string, existing.end_date as string, 'This availability entry',
      );
      await assertProviderInSiteOrg(sb, ctx.siteId, existing.provider_id as string);
      // Soft-cancel (never hard-delete): a canceled entry stops blocking /
      // flagging via isDismissedAvailability while the row is kept for history.
      const { data, error } = await sb
        .from('provider_availability')
        .update({ approval_status: 'canceled' })
        .eq('id', parsed.id)
        .select()
        .single();
      if (error) throw new Error(`availability cancel failed: ${error.message}`);
      return {
        summary: `Canceled availability entry ${parsed.id}`,
        result: { ok: true, availability: data },
      };
    },

    async update_provider_profile(sb, ctx, input) {
      const parsed = parseWith(UpdateProfileInputSchema, input);
      const { provider_id, ...patch } = parsed;
      if (Object.keys(patch).length === 0) {
        throw new ToolInputError(
          'Provide at least one field to update: fte_value, call_taker, partial_call_taker, or is_day_doc.',
        );
      }
      // Org guard: the snapshot captures profiles org-wide (engines read them
      // regardless of home site), so writes must stay inside the org too —
      // an out-of-org profile edit would escape undo entirely.
      await assertProviderInSiteOrg(sb, ctx.siteId, provider_id);
      // UPDATE only — never create a profile row. A fresh row would ship every
      // other column at its default (e.g. call_taker=false) AND, being absent
      // from the snapshot's org-wide profile capture, could not be undone
      // (profiles restore by upsert; there is no delete-new pass for them).
      // A missing profile is surfaced for the scheduler to fix.
      const { data, error } = await sb
        .from('provider_employment_profiles')
        .update(patch)
        .eq('provider_id', provider_id)
        .select();
      if (error) throw new Error(`profile update failed: ${error.message}`);
      const rows = (data ?? []) as unknown[];
      if (rows.length === 0) {
        throw new ToolInputError(
          `No employment profile exists for provider ${provider_id} — create one in the Providers UI before setting FTE / call-pool flags.`,
        );
      }
      return {
        summary: `Updated profile for provider ${provider_id} (${Object.keys(patch).join(', ')})`,
        result: { ok: true, profile: rows[0] },
      };
    },

    async update_site_credentials(sb, ctx, input) {
      const parsed = parseWith(UpdateCredentialsInputSchema, input);
      const { provider_id, ...patch } = parsed;
      if (Object.keys(patch).length === 0) {
        throw new ToolInputError(
          'Provide at least one field to update: can_take_call, can_take_weekend_call, or can_take_holiday_call.',
        );
      }
      // UPDATE only, scoped to ctx.siteId's credential row. If none exists we
      // surface it (spec: never invent a credential row silently — the
      // scheduler decides) instead of inserting one with default eligibility.
      const { data, error } = await sb
        .from('provider_site_credentials')
        .update(patch)
        .eq('provider_id', provider_id)
        .eq('site_id', ctx.siteId)
        .select();
      if (error) throw new Error(`site credential update failed: ${error.message}`);
      const rows = (data ?? []) as unknown[];
      if (rows.length === 0) {
        throw new ToolInputError(
          `No site-credential row exists for provider ${provider_id} at this site (site_id ${ctx.siteId}). Call-eligibility can only be set on an existing credential row — create one in the Providers UI (site credentials) first, then retry.`,
        );
      }
      return {
        summary: `Updated site credentials for provider ${provider_id} (${Object.keys(patch).join(', ')})`,
        result: { ok: true, credential: rows[0] },
      };
    },

    async regenerate_schedule(sb, ctx) {
      // Exactly the generate route's engine invocation: call pass first, then
      // day-shift pass only when the call pass loaded a usable context.
      const result = await engine.autoGenerate(sb, ctx.versionId, {
        overrideProviderIds: ctx.overrideProviderIds,
      });
      if (result.ok) {
        const dayResult = await engine.autoGenerateDayShifts(sb, ctx.versionId, {
          overrideProviderIds: ctx.overrideProviderIds,
        });
        result.filled += dayResult.filled;
        result.errors.push(...dayResult.errors);
      }
      const unfilled = trimUnfilled(result.unfilled);
      return {
        summary: `Regenerated: ${result.filled} filled, ${result.unfilled.length} unfilled${result.warnings.length ? `, ${result.warnings.length} warning(s)` : ''}`,
        result: {
          ok: result.ok,
          filled: result.filled,
          skipped: result.skipped,
          unfilled,
          warnings: result.warnings,
          skippedDerived: result.skippedDerived ?? [],
          errors: result.errors,
          metrics: result.metrics ?? null,
        },
      };
    },
  };
}
